class Solution {
public:
    int countNumbersWithUniqueDigits(int n) {
        if (n == 0) return 1;
        int result = 10;
        int current = 9;
        for (int i = 2; i <= n; i++) {
            current *= (11 - i);
            result += current;
        }
        return result;
    }
};
